begin;
select no_plan();
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
insert into cooksmith.planned_meals(id,household_id,meal_date,meal_type,title) values('80000000-0000-4000-8000-000000000079','20000000-0000-4000-8000-000000000001','2026-10-04','dinner','Synthetic grouped purchase');
select cooksmith.reconcile_planned_meal_shopping('20000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000079','[{"name":"sea salt","quantity":50,"unit":"g","category":"pantry"},{"name":"sea salt","quantity":2,"unit":"tsp","category":"pantry"}]');
create temporary table purchase_members as select id,unit from cooksmith.shopping_list_items where household_id='20000000-0000-4000-8000-000000000001' and display_name='sea salt';
select lives_ok($$select cooksmith.set_shopping_purchase_completed('20000000-0000-4000-8000-000000000001',(select array_agg(id) from purchase_members),true)$$,'One action completes every unit member');
select is((select count(*)::integer from cooksmith.shopping_list_items where id in(select id from purchase_members) and completed),2,'Both members are complete');
select lives_ok($$select cooksmith.set_shopping_purchase_completed('20000000-0000-4000-8000-000000000001',(select array_agg(id) from purchase_members),true)$$,'Completion retry is idempotent');
select throws_ok($$select cooksmith.set_shopping_purchase_completed('20000000-0000-4000-8000-000000000001',(select array_agg(id)||array['90000000-0000-4000-8000-000000000099'::uuid] from purchase_members),false)$$,'42501',null,'A mixed valid/invalid set is rejected atomically');
select is((select count(*)::integer from cooksmith.shopping_list_items where id in(select id from purchase_members) and completed),2,'Failed grouped completion leaves both members unchanged');
select lives_ok($$select cooksmith.update_shopping_purchase('20000000-0000-4000-8000-000000000001',(select jsonb_agg(jsonb_build_object('id',id,'name','sea salt','quantity',case unit when 'g' then 60 else 15 end,'unit',case unit when 'g' then 'g' else 'ml' end,'category','pantry')) from purchase_members))$$,'A household can adjust the combined amounts atomically');
select is((select count(*)::integer from cooksmith.shopping_item_contributions where planned_meal_id='80000000-0000-4000-8000-000000000079'),2,'Both original recipe contributions remain');
select is((select count(*)::integer from cooksmith.shopping_list_items where id in(select id from purchase_members) and manual and plan_override),2,'Explicit adjustments are protected as plan overrides');
select cooksmith.reconcile_planned_meal_shopping('20000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000079','[{"name":"sea salt","quantity":50,"unit":"g","category":"pantry"},{"name":"sea salt","quantity":2,"unit":"tsp","category":"pantry"}]');
select results_eq($$select quantity,unit from cooksmith.shopping_list_items where household_id='20000000-0000-4000-8000-000000000001' and display_name='sea salt' order by unit$$,$$values (60::numeric,'g'::text),(15::numeric,'ml'::text)$$,'Plan regeneration retains adjustments without doubling planned ingredients');
select throws_ok($$select cooksmith.update_shopping_purchase('20000000-0000-4000-8000-000000000001',(select jsonb_agg(jsonb_build_object('id',id,'name','sea salt','quantity',case unit when 'g' then 99 else -1 end,'unit',unit,'category','pantry') order by unit) from purchase_members))$$,'23514',null,'One invalid amount rejects the whole edit');
select is((select quantity from cooksmith.shopping_list_items where id=(select id from purchase_members where unit='g')),60::numeric,'Earlier valid changes roll back with the rejected edit');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000003',true);
select throws_ok($$select cooksmith.remove_shopping_purchase('20000000-0000-4000-8000-000000000001',(select array_agg(id) from purchase_members))$$,'42501',null,'Another household cannot remove this purchase');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select lives_ok($$select cooksmith.remove_shopping_purchase('20000000-0000-4000-8000-000000000001',(select array_agg(id) from purchase_members))$$,'One removal deletes all purchase members');
select is((select count(*)::integer from cooksmith.shopping_item_contributions where planned_meal_id='80000000-0000-4000-8000-000000000079'),0,'Removal cleans up corresponding contribution links');
-- A changed amount becomes outstanding; equivalent regeneration stays bought.
select cooksmith.reconcile_planned_meal_shopping('20000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000079','[{"name":"review oil","quantity":2,"unit":"tsp.","category":"pantry"}]');
select is((select quantity from cooksmith.shopping_list_items where display_name='review oil'),10::numeric,'Metric teaspoon punctuation converts to mL in SQL');
select cooksmith.set_shopping_purchase_completed('20000000-0000-4000-8000-000000000001',(select array_agg(id) from cooksmith.shopping_list_items where display_name='review oil'),true);
select cooksmith.reconcile_planned_meal_shopping('20000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000079','[{"name":"review oil","quantity":10,"unit":"ml","category":"pantry"}]');
select ok((select completed from cooksmith.shopping_list_items where display_name='review oil'),'Equivalent regeneration preserves bought state');
select cooksmith.reconcile_planned_meal_shopping('20000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000079','[{"name":"review oil","quantity":15,"unit":"ml","category":"pantry"}]');
select ok(not (select completed from cooksmith.shopping_list_items where display_name='review oil'),'Increased requirements become outstanding');
reset role;
select ok(not has_function_privilege('anon','cooksmith.update_shopping_purchase(uuid,jsonb)','EXECUTE'),'Anonymous users cannot call grouped edits');
select * from finish();
rollback;
